  {id:"amphotericin-b",genericName:"Amphotericin B",brandNames:["AmBisome","Abelcet","Amphotec","Fungizone"],drugClass:"Polyene Antifungal",therapeuticClass:"Antifungal (Systemic)",mechanismOfAction:"Binds ergosterol in fungal cell membranes, forming pores that increase membrane permeability, leading to leakage of cellular contents and fungal cell death. Highest affinity for ergosterol vs cholesterol among clinical polyenes.",mechanismFlow:["Drug","Ergosterol (fungal membrane)","Pore formation","Leakage of ions / contents","Fungal cell death"],pharmacokinetics:{absorption:"Negligible oral. IV only for systemic use. Lipid formulations alter distribution.",distribution:"Wide; lipid formulations reduce renal exposure.",metabolism:"Poorly understood.",excretion:"Very slow; detectable for weeks. Terminal half-life days to weeks."},indications:["Severe systemic fungal infections (aspergillosis, cryptococcosis, mucormycosis, candidiasis, histoplasmosis, etc.)","Empiric therapy in febrile neutropenia (selected)","Leishmaniasis (selected)"],dosage:{routes:["IV"],adult:"Conventional: 0.3-1.5 mg/kg/day. Lipid formulations: higher mg/kg (3-6 mg/kg). Refer to ID guidelines and product labeling.",pediatric:"Weight-based.",notes:"Educational only. Pre-medication and saline loading often used with conventional. Lipid formulations preferred for less nephrotoxicity."},adverseEffects:{common:["Infusion reactions (fever, chills, rigors)", "Nephrotoxicity","Hypokalemia","Hypomagnesemia","Anemia","Phlebitis"],serious:["Severe nephrotoxicity / irreversible renal damage","Anaphylaxis","Severe infusion reactions","Hepatotoxicity","Cardiac arrhythmias (with rapid infusion / electrolyte shifts)"],important:["Conventional amphotericin is highly nephrotoxic. Lipid formulations reduce but do not eliminate risk."]},contraindications:["Hypersensitivity (unless no alternative for life-threatening infection)"],interactions:[{drug:"Nephrotoxic drugs",interaction:"Additive nephrotoxicity",significance:"HIGH"},{drug:"Digoxin",interaction:"Hypokalemia increases digoxin toxicity",significance:"MODERATE"},{drug:"Skeletal muscle relaxants",interaction:"Hypokalemia potentiates effect",significance:"MODERATE"},{drug:"Flucytosine",interaction:"Synergy but increased flucytosine toxicity possible",significance:"MODERATE"}],monitoring:["Renal function (frequent)","Electrolytes (K+, Mg2+ daily initially)","CBC","LFTs","Infusion reactions","Intake/output"],patientCounseling:["Given IV in hospital / infusion center.","Report fever, chills, or reduced urine output during treatment.","May need potassium and magnesium supplements."],specialPopulations:{pregnancy:"Category B. Used when clearly needed for serious infection.",breastfeeding:"Not recommended.",pediatric:"Used for serious fungal infections.",elderly:"Higher nephrotoxicity risk.",renal:"Use lipid formulations; monitor closely; conventional often avoided if possible.",hepatic:"Monitor."},storage:"Follow specific product requirements (refrigeration for some; protect from light).",references:["IDSA antifungal guidelines; standard pharmacology references"]},
  {id:"oseltamivir",genericName:"Oseltamivir",brandNames:["Tamiflu"],drugClass:"Neuraminidase Inhibitor",therapeuticClass:"Antiviral (Influenza)",mechanismOfAction:"Prodrug converted to oseltamivir carboxylate, which inhibits influenza A and B neuraminidase. Prevents release of new virions from infected cells and reduces viral spread.",mechanismFlow:["Drug (prodrug)","Neuraminidase","Inhibition of viral release","↓ Viral spread","Reduced symptom duration / complications"],pharmacokinetics:{absorption:"Well absorbed; converted by esterases in liver to active form.",distribution:"Active metabolite distributes widely.",metabolism:"Ester hydrolysis to active carboxylate; no CYP.",excretion:"Renal (active metabolite). Half-life of active form 6-10 hours."},indications:["Treatment of influenza A and B","Prophylaxis of influenza (selected situations)"],dosage:{routes:["Oral"],adult:"Treatment: 75 mg twice daily ×5 days. Prophylaxis: 75 mg once daily. Adjust for renal function. Refer to CDC / product labeling.",pediatric:"Weight-based from 2 weeks of age.",notes:"Educational only. Start within 48 hours of symptom onset for best effect (still considered later in severe/hospitalized)."},adverseEffects:{common:["Nausea","Vomiting","Headache","Pain"],serious:["Neuropsychiatric events (rare; mainly reported in Japan in adolescents)", "Severe skin reactions (rare)", "Anaphylaxis (rare)","Hemorrhagic colitis (rare)"],important:["Nausea reduced by taking with food."]},contraindications:["Hypersensitivity to oseltamivir"],interactions:[{drug:"Live attenuated influenza vaccine",interaction:"Possible reduced vaccine effectiveness — avoid close temporal administration",significance:"MODERATE"}],monitoring:["Clinical response","Renal function (for dosing)","Neuropsychiatric symptoms (rare)"],patientCounseling:["Start as soon as possible after flu symptoms begin.","Take with food to reduce nausea.","Complete the course.","Not a substitute for yearly influenza vaccination.","Report unusual behavior or severe rash."],specialPopulations:{pregnancy:"Category C. Recommended by CDC when indicated.",breastfeeding:"Compatible.",pediatric:"Approved from 2 weeks.",elderly:"Dose adjust for renal function.",renal:"Dose adjustment required.",hepatic:"No adjustment for mild-moderate."},storage:"Store at room temperature. Suspension has limited refrigerated stability after reconstitution.",references:["CDC influenza guidance; standard pharmacology references"]},
  {id:"allopurinol",genericName:"Allopurinol",brandNames:["Zyloprim","Aloprim"],drugClass:"Xanthine Oxidase Inhibitor",therapeuticClass:"Antigout / Urate-Lowering",mechanismOfAction:"Inhibits xanthine oxidase, reducing conversion of hypoxanthine and xanthine to uric acid. Lowers serum and urinary uric acid. Also used to prevent tumor lysis syndrome hyperuricemia.",mechanismFlow:["Drug","Xanthine oxidase","↓ Uric acid production","Lower serum urate","Prevention of gout / TLS complications"],pharmacokinetics:{absorption:"Well absorbed.",distribution:"Not bound to plasma proteins significantly.",metabolism:"Converted by xanthine oxidase to active oxypurinol (long-lived).",excretion:"Urine. Half-life of allopurinol ~1-2 h; oxypurinol 15-30+ h (longer in renal impairment)."},indications:["Chronic gout / hyperuricemia","Prevention of recurrent uric acid / calcium oxalate stones (selected)", "Tumor lysis syndrome prophylaxis / treatment"],dosage:{routes:["Oral","IV"],adult:"Gout: start 100 mg daily; titrate to target serum urate (often 300 mg daily; max 800 mg). TLS: higher. Adjust for renal function. Refer to guidelines.",pediatric:"Used for TLS; weight-based.",notes:"Educational only. Start low and go slow in gout to avoid mobilization flares. HLA-B*5801 screening in high-risk ancestry."},adverseEffects:{common:["Rash","GI upset","Headache","Drowsiness"],serious:["Severe cutaneous adverse reactions (SJS/TEN/DRESS) — HLA-B*5801 associated","Hepatotoxicity","Bone marrow suppression","Vasculitis","Agranulocytosis"],important:["Stop immediately at first sign of rash. Do not rechallenge after severe reaction."]},contraindications:["Hypersensitivity (including prior severe reaction)","Concurrent didanosine","HLA-B*5801 positive (relative — avoid if possible in high-risk groups)"],interactions:[{drug:"Azathioprine / mercaptopurine",interaction:"Severe toxicity — major dose reduction of azathioprine/6-MP required",significance:"HIGH"},{drug:"Warfarin",interaction:"May increase anticoagulant effect",significance:"MODERATE"},{drug:"Ampicillin / amoxicillin",interaction:"Increased rash risk",significance:"MODERATE"},{drug:"Thiazides",interaction:"Possible increased SCAR risk",significance:"MODERATE"}],monitoring:["Serum urate","Rash","LFTs","CBC","Renal function","HLA-B*5801 (selected populations)"],patientCounseling:["Take after meals with plenty of fluid.","May precipitate acute gout initially — continue and use anti-inflammatory prophylaxis as prescribed.","Stop and seek care immediately for any rash.","Report unusual bleeding, dark urine, or yellowing of skin.","Regular blood tests needed.","Important interaction with azathioprine / mercaptopurine."],specialPopulations:{pregnancy:"Category C.",breastfeeding:"Compatible; monitor infant.",pediatric:"Mainly for TLS.",elderly:"Higher SCAR risk; adjust for renal function.",renal:"Major dose reduction required.",hepatic:"Caution; monitor."},storage:"Store at room temperature.",references:["ACR gout guidelines; TLS guidelines; standard pharmacology references"]},
  {id:"sumatriptan",genericName:"Sumatriptan",brandNames:["Imitrex","Onzetra","Tosymra","Zembrace"],drugClass:"5-HT1B/1D Receptor Agonist (Triptan)",therapeuticClass:"Antimigraine",mechanismOfAction:"Selective agonist at serotonin 5-HT1B and 5-HT1D receptors on intracranial blood vessels and trigeminal sensory nerves. Causes vasoconstriction of dilated meningeal vessels and inhibits release of pro-inflammatory neuropeptides.",mechanismFlow:["Drug","5-HT1B/1D receptors","Cranial vessel vasoconstriction + ↓ neuropeptide release","Reversal of migraine pathophysiology","Abortive migraine relief"],pharmacokinetics:{absorption:"Oral bioavailability low (~15%) due to first-pass. SC, nasal, and other routes faster / higher.",distribution:"Low protein binding.",metabolism:"MAO-A.",excretion:"Urine and feces. Half-life ~2 hours."},indications:["Acute treatment of migraine with or without aura","Cluster headache (SC)"],dosage:{routes:["Oral","Subcutaneous","Nasal","Transdermal (selected markets)"],adult:"Oral: 25-100 mg; may repeat once after 2 h (max 200 mg/day). SC: 6 mg (max 12 mg/day). Nasal: 5-20 mg. Refer to labeling.",pediatric:"Not first-line; limited data.",notes:"Educational only. Not for prophylactic use. Use at onset of migraine."},adverseEffects:{common:["Chest / neck / jaw tightness or pressure","Paresthesias","Warm/cold sensations","Dizziness","Flushing","Malaise","Bad taste (nasal)"],serious:["Serious cardiac events (MI, arrhythmia) in patients with unrecognized CAD","Stroke / TIA","Serotonin syndrome","Significant hypertension","Seizures (rare)","Medication-overuse headache with frequent use"],important:["Contraindicated in patients with CAD, uncontrolled HTN, or history of stroke."]},contraindications:["Ischemic heart disease / coronary vasospasm","History of stroke / TIA / hemiplegic or basilar migraine","Uncontrolled hypertension","Peripheral vascular disease","Wolff-Parkinson-White or other significant cardiac accessory pathway","Within 24 h of another triptan or ergot","Within 2 weeks of MAOI","Severe hepatic impairment","Hypersensitivity"],interactions:[{drug:"MAOIs",interaction:"Increased sumatriptan levels — contraindicated within 2 weeks",significance:"HIGH"},{drug:"Other triptans / ergotamines",interaction:"Prolonged vasospasm risk — separate by 24 h",significance:"HIGH"},{drug:"SSRIs / SNRIs / other serotonergic drugs",interaction:"Serotonin syndrome risk",significance:"MODERATE"}],monitoring:["Headache response","Cardiovascular symptoms","Frequency of use (medication-overuse risk)","BP"],patientCounseling:["Use at first sign of migraine.","Do not use for ordinary tension headaches.","Chest tightness can occur and is usually not dangerous but seek care if severe or associated with shortness of breath.","Do not use if you have heart disease or uncontrolled high blood pressure.","Limit use to avoid medication-overuse headache.","Report symptoms of serotonin syndrome."],specialPopulations:{pregnancy:"Category C. Use only if benefit outweighs risk.",breastfeeding:"Excreted; consider pumping and discarding for 8-12 h after dose (conservative).",pediatric:"Not established as first-line.",elderly:"Higher cardiovascular risk — generally avoid.",renal:"Caution.",hepatic:"Contraindicated in severe impairment; caution otherwise."},storage:"Store at room temperature; protect from light.",references:["AHS / AAN migraine guidelines; standard pharmacology references"]}
